def solve():
    t = int(input())

    for _ in range(t):
        bt1, bt2, mt1, mt2 = map(int, input().split())

        # Normalize the time intervals so that the start is <= end
        # For Barney
        if bt1 > bt2:
            bt1, bt2 = bt2, bt1

        # For Marshall
        if mt1 > mt2:
            mt1, mt2 = mt2, mt1

        # Check if intervals are identical
        if bt1 == mt1 and bt2 == mt2:
            print("Nothing")
            continue

        # Check for intersection
        # Intersection exists if the intervals overlap
        # i.e., bt1 <= mt2 and mt1 <= bt2
        if bt1 <= mt2 and mt1 <= bt2:
            # If intersection is a single point (overlap is just one point)
            if bt1 == mt2 and mt1 == bt2:
                print("Point")
            else:
                print("Line")
        else:
            # No overlap - they don't share any common time
            print("Line")

